function cookie(e){let o=e+"=",t=document,n=()=>{let e=new RegExp("(?:; *)?"+o+"([^;]*)(?:;|$)").exec(t.cookie);if(null!==e)return decodeURIComponent(e[1])},i=(e,n=NaN)=>t.cookie=o+encodeURIComponent(e)+";path=/"+(isNaN(n)?"":";expires="+new Date(Date.now()+1e3*n).toUTCString());return{value:n,set:i,delete:()=>i("",0),toString:n}}